int fd_in = 3, fd_out = 4;
size_t len = 4096;
off_t off_src = 1024;
ssize_t transferred;

// Use explicit source offset (updated by kernel)
// Destination uses current file offset (NULL)
transferred = copy_file_range(
    fd_in, &off_src,
    fd_out, NULL,
    len, 0
);

// Use current file offsets for both source and destination (NULL)
// Offsets must be updated in the kernel/file description table
transferred = copy_file_range(
    fd_in, NULL,
    fd_out, NULL,
    len, 0
);
